function AsyncapiForgePure(){
  function rep(n){ var s = ''; for (var i = 0; i < n; i++) s += ' '; return s; }

  function stripComment(t){
    var q = null, out = '';
    for (var i = 0; i < t.length; i++){
      var c = t[i];
      if (q){ if (c === q) q = null; out += c; continue; }
      if (c === '"' || c === "'"){ q = c; out += c; continue; }
      if (c === '#' && (i === 0 || t[i-1] === ' ')) break;
      out += c;
    }
    return out.replace(/\s+$/, '');
  }

  function tokenize(src){
    var raw = String(src == null ? '' : src).replace(/\r\n/g, '\n').replace(/\t/g, '  ').split('\n');
    var out = [];
    for (var i = 0; i < raw.length; i++){
      var ln = raw[i].replace(/\s+$/, '');
      var ind = 0; while (ind < ln.length && ln[ind] === ' ') ind++;
      var body = ln.slice(ind);
      out.push({no:i+1, indent:ind, text:body, blank:(body === '')});
    }
    return out;
  }

  function findKeyColon(t){
    var q = null, depth = 0;
    for (var i = 0; i < t.length; i++){
      var c = t[i];
      if (q){ if (c === q) q = null; continue; }
      if (c === '"' || c === "'"){ q = c; continue; }
      if (c === '[' || c === '{') depth++;
      else if (c === ']' || c === '}') depth--;
      else if (c === ':' && depth === 0){
        if (i + 1 >= t.length || t[i+1] === ' ') return i;
      }
    }
    return -1;
  }

  function splitFlow(s){
    var parts = [], depth = 0, q = null, cur = '';
    for (var i = 0; i < s.length; i++){
      var c = s[i];
      if (q){ cur += c; if (c === q) q = null; continue; }
      if (c === '"' || c === "'"){ q = c; cur += c; continue; }
      if (c === '[' || c === '{'){ depth++; cur += c; continue; }
      if (c === ']' || c === '}'){ depth--; cur += c; continue; }
      if (c === ',' && depth === 0){ parts.push(cur.trim()); cur = ''; continue; }
      cur += c;
    }
    if (cur.trim() !== '') parts.push(cur.trim());
    return parts;
  }

  function unquote(s){
    s = s.trim();
    if (s.length >= 2){
      if (s[0] === '"' && s[s.length-1] === '"'){
        return s.slice(1, -1).replace(/\\n/g, '\n').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
      }
      if (s[0] === "'" && s[s.length-1] === "'") return s.slice(1, -1).replace(/''/g, "'");
    }
    return s;
  }

  function scalar(s){
    s = s.trim();
    if (s === '') return '';
    if (s[0] === '"' || s[0] === "'") return unquote(s);
    if (s[0] === '[' && s[s.length-1] === ']'){
      var b = s.slice(1, -1).trim();
      if (b === '') return [];
      var ps = splitFlow(b), arr = [];
      for (var i = 0; i < ps.length; i++) arr.push(scalar(ps[i]));
      return arr;
    }
    if (s[0] === '{' && s[s.length-1] === '}'){
      var b2 = s.slice(1, -1).trim(), o = {};
      if (b2 === '') return o;
      var ps2 = splitFlow(b2);
      for (var j = 0; j < ps2.length; j++){
        var ci = findKeyColon(ps2[j]);
        if (ci < 0){ o[unquote(ps2[j])] = null; continue; }
        o[unquote(ps2[j].slice(0, ci))] = scalar(ps2[j].slice(ci+1));
      }
      return o;
    }
    if (/^(true|yes)$/i.test(s)) return true;
    if (/^(false|no)$/i.test(s)) return false;
    if (/^(null|~)$/i.test(s)) return null;
    if (/^-?\d+$/.test(s)) return parseInt(s, 10);
    if (/^-?\d*\.\d+$/.test(s)) return parseFloat(s);
    return s;
  }

  function nextReal(lines, i){
    while (i < lines.length){
      if (lines[i].blank){ i++; continue; }
      if (stripComment(lines[i].text) === ''){ i++; continue; }
      return i;
    }
    return -1;
  }

  function readBlockScalar(lines, st, indent, marker){
    var folded = marker.charAt(0) === '>';
    var chomp = /-/.test(marker) ? '-' : (/\+/.test(marker) ? '+' : '');
    var buf = [], base = -1;
    while (st.i < lines.length){
      var L = lines[st.i];
      if (L.blank){ buf.push(''); st.i++; continue; }
      if (L.indent <= indent) break;
      if (base < 0) base = L.indent;
      buf.push(rep(Math.max(0, L.indent - base)) + L.text);
      st.i++;
    }
    while (buf.length && buf[buf.length-1] === '') buf.pop();
    var s = folded ? buf.join(' ') : buf.join('\n');
    if (chomp !== '-' && s !== '') s += '\n';
    return s;
  }

  function collectChild(lines, st, indent, ctx){
    var k = nextReal(lines, st.i);
    if (k < 0) return null;
    var L = lines[k];
    if (L.indent > indent){ st.i = k; return parseNode(lines, st, L.indent, ctx); }
    if (L.indent === indent){
      var t = stripComment(L.text);
      if (t.charAt(0) === '-' && (t.length === 1 || t.charAt(1) === ' ')){ st.i = k; return parseSeq(lines, st, indent, ctx); }
    }
    return null;
  }

  function parseNode(lines, st, indent, ctx){
    var k = nextReal(lines, st.i);
    if (k < 0) return null;
    st.i = k;
    var t = stripComment(lines[k].text);
    if (t.charAt(0) === '-' && (t.length === 1 || t.charAt(1) === ' ')) return parseSeq(lines, st, indent, ctx);
    return parseMap(lines, st, indent, ctx);
  }

  function parseMap(lines, st, indent, ctx){
    var obj = {}; ctx.meta.push(obj);
    // 行号元数据设为不可枚举，避免 Object.keys / for-in / JSON.stringify 把它当成文档里的真实字段
    Object.defineProperty(obj, '__lines', {value:{}, enumerable:false, writable:true, configurable:true});
    while (st.i < lines.length){
      var L = lines[st.i];
      if (L.blank){ st.i++; continue; }
      var t = stripComment(L.text);
      if (t === ''){ st.i++; continue; }
      if (L.indent < indent) break;
      if (L.indent > indent){ ctx.errors.push('第 ' + L.no + ' 行缩进异常（多出 ' + (L.indent - indent) + ' 空格）'); st.i++; continue; }
      if (t.charAt(0) === '-') break;
      var ci = findKeyColon(t);
      if (ci < 0){ ctx.errors.push('第 ' + L.no + ' 行不是合法键值对：' + t); st.i++; continue; }
      var key = unquote(t.slice(0, ci));
      var rest = t.slice(ci+1).trim();
      obj.__lines[key] = L.no;
      st.i++;
      if (rest === ''){
        obj[key] = collectChild(lines, st, indent, ctx);
      } else if (/^[|>][-+]?\d*$/.test(rest)){
        obj[key] = readBlockScalar(lines, st, indent, rest);
      } else {
        obj[key] = scalar(rest);
      }
    }
    return obj;
  }

  function parseSeq(lines, st, indent, ctx){
    var arr = [];
    while (st.i < lines.length){
      var L = lines[st.i];
      if (L.blank){ st.i++; continue; }
      var t = stripComment(L.text);
      if (t === ''){ st.i++; continue; }
      if (L.indent !== indent) break;
      if (!(t.charAt(0) === '-' && (t.length === 1 || t.charAt(1) === ' '))) break;
      var after = t.slice(1);
      var lead = after.length - after.replace(/^ +/, '').length;
      var rest = after.slice(lead);
      if (rest === ''){
        st.i++;
        arr.push(collectChild(lines, st, indent, ctx));
      } else {
        var ni = indent + 1 + lead;
        lines[st.i] = {no:L.no, indent:ni, text:rest, blank:false};
        if (findKeyColon(rest) >= 0) arr.push(parseMap(lines, st, ni, ctx));
        else if (rest.charAt(0) === '-') arr.push(parseSeq(lines, st, ni, ctx));
        else { arr.push(scalar(rest)); st.i++; }
      }
    }
    return arr;
  }

  function parseYaml(src){
    if (String(src == null ? '' : src).trim() === '') return {error:'请输入 AsyncAPI 文档'};
    var lines = tokenize(src);
    var ctx = {errors:[], meta:[]};
    var st = {i:0};
    var doc = parseNode(lines, st, 0, ctx);
    if (doc === null) return {error:'未解析出任何内容（是否全为注释？）'};
    if (Object.prototype.toString.call(doc) !== '[object Object]') return {error:'AsyncAPI 文档顶层必须是映射（key: value），当前是序列'};
    return {value:doc, errors:ctx.errors};
  }


  // ---------------- 通用工具 ----------------
  function isMap(v){ return Object.prototype.toString.call(v) === '[object Object]'; }
  function keys(v){ return isMap(v) ? Object.keys(v) : []; }

  function parseDoc(src){
    var s = String(src == null ? '' : src).trim();
    if (s === '') return {error:'请输入 AsyncAPI 文档（YAML 或 JSON）'};
    if (s.charAt(0) === '{'){
      try { return {value:JSON.parse(s), errors:[], format:'json'}; }
      catch (e){ return {error:'JSON 解析失败：' + e.message}; }
    }
    var r = parseYaml(s);
    if (r.error) return r;
    r.format = 'yaml';
    return r;
  }

  // ---------------- 版本识别 ----------------
  function detectVersion(doc){
    if (!isMap(doc)) return {error:'文档顶层必须是映射'};
    var v = doc['asyncapi'];
    if (v === undefined){
      if (doc['openapi'] !== undefined) return {error:'这是 OpenAPI 文档而不是 AsyncAPI，顶层键应为 asyncapi'};
      if (doc['swagger'] !== undefined) return {error:'这是 Swagger 2.0 文档而不是 AsyncAPI'};
      return {error:'缺少顶层 asyncapi 版本字段'};
    }
    var s = String(v);
    var m = /^(\d+)\.(\d+)(?:\.(\d+))?$/.exec(s);
    if (!m) return {error:'asyncapi 版本格式非法：' + s};
    var major = parseInt(m[1], 10);
    return {value:{raw:s, major:major, minor:parseInt(m[2], 10),
                   generation:major >= 3 ? 'v3' : (major === 2 ? 'v2' : 'legacy')}};
  }

  // ---------------- 协议常识 ----------------
  var PROTOCOLS = {
    kafka:      {defaultPort:9092,  bindingKey:'kafka',  note:'分区键决定顺序性，消费组决定并发上限'},
    'kafka-secure':{defaultPort:9093, bindingKey:'kafka', note:'走 TLS 的 Kafka，务必核对 SASL 机制'},
    amqp:       {defaultPort:5672,  bindingKey:'amqp',   note:'交换机与路由键语义要写进 bindings，否则实现方只能猜'},
    mqtt:       {defaultPort:1883,  bindingKey:'mqtt',   note:'主题层级用斜杠，通配符 + 与 # 只在订阅侧有效'},
    ws:         {defaultPort:80,    bindingKey:'ws',     note:'WebSocket 建议叠加心跳与重连退避'},
    wss:        {defaultPort:443,   bindingKey:'ws',     note:'生产环境应始终使用 wss'},
    nats:       {defaultPort:4222,  bindingKey:'nats',   note:'主题用点号分层，队列组实现负载均衡'},
    redis:      {defaultPort:6379,  bindingKey:'redis',  note:'发布订阅不持久化，掉线即丢消息'},
    sqs:        {defaultPort:443,   bindingKey:'sqs',    note:'至少一次投递，消费端必须幂等'},
    sns:        {defaultPort:443,   bindingKey:'sns',    note:'扇出投递，注意订阅端的重复与乱序'},
    jms:        {defaultPort:61616, bindingKey:'jms',    note:'队列与主题语义不同，别混用'},
    stomp:      {defaultPort:61613, bindingKey:'stomp',  note:'确认模式决定重投行为'},
    http:       {defaultPort:80,    bindingKey:'http',   note:'HTTP 回调式事件要考虑重试与签名校验'},
    https:      {defaultPort:443,   bindingKey:'http',   note:'Webhook 必须校验来源签名'},
    googlepubsub:{defaultPort:443,  bindingKey:'googlepubsub', note:'至少一次投递，确认截止时间要大于处理耗时'},
    pulsar:     {defaultPort:6650,  bindingKey:'pulsar', note:'租户与命名空间是隔离边界'}
  };

  function protocolInfo(p){
    var k = String(p == null ? '' : p).toLowerCase();
    return PROTOCOLS[k] || null;
  }

  // ---------------- 引用解析 ----------------
  function resolveRef(doc, ref){
    var s = String(ref == null ? '' : ref);
    if (s.indexOf('#/') !== 0) return {error:'只支持文档内引用（以 #/ 开头），收到：' + s};
    var parts = s.slice(2).split('/'), cur = doc;
    for (var i = 0; i < parts.length; i++){
      var seg = parts[i].replace(/~1/g, '/').replace(/~0/g, '~');
      if (!isMap(cur) || cur[seg] === undefined) return {error:'引用指向不存在的节点：' + s};
      cur = cur[seg];
    }
    return {value:cur, path:s};
  }

  // ---------------- 通道地址风格 ----------------
  function addressStyle(addr){
    var a = String(addr == null ? '' : addr);
    if (a === '') return {style:'empty'};
    var slash = (a.match(/\//g) || []).length;
    var dot = (a.match(/\./g) || []).length;
    return {style:slash > dot ? 'slash' : (dot > 0 ? 'dot' : 'flat'),
            segments:slash > dot ? a.split('/').filter(function(x){ return x; }).length : a.split('.').length,
            hasParam:/\{[^}]+\}/.test(a),
            wildcard:/[+#*>]/.test(a)};
  }

  // ---------------- 主体校验 ----------------
  function lint(doc){
    var iss = [];
    function add(level, text){ iss.push({level:level, text:text}); }
    function err(t){ add('error', t); }
    function warn(t){ add('warn', t); }
    function ok(t){ add('ok', t); }

    var ver = detectVersion(doc);
    if (ver.error) return {issues:[{level:'error', text:ver.error}], errors:1, warnings:0, ok:false, version:null};

    if (ver.value.generation === 'v2'){
      warn('文档是 AsyncAPI ' + ver.value.raw + '，3.0 已把 publish/subscribe 换成顶层 operations 与 action，建议迁移');
    } else if (ver.value.generation === 'legacy'){
      err('AsyncAPI ' + ver.value.raw + ' 过于陈旧，工具链基本不再支持');
    } else {
      ok('使用 AsyncAPI ' + ver.value.raw);
    }
    var v3 = ver.value.generation === 'v3';

    // info
    var info = doc['info'];
    if (!isMap(info)) err('缺少 info 对象');
    else {
      if (!info['title']) err('info.title 必填');
      if (!info['version']) err('info.version 必填');
      if (!info['description']) warn('建议补充 info.description，消费方需要知道这套事件的业务含义');
      if (v3 && !info['contact'] && !info['license']) warn('未声明 contact 或 license，出问题时找不到责任人');
    }

    // servers
    var servers = doc['servers'];
    if (!isMap(servers) || !keys(servers).length) warn('未声明任何 server，消费方无从得知接入地址');
    else {
      var sk = keys(servers);
      for (var i = 0; i < sk.length; i++){
        var sv = servers[sk[i]], label = 'servers.' + sk[i];
        if (!isMap(sv)){ err(label + ' 必须是映射'); continue; }
        if (v3){
          if (!sv['host']) err(label + '.host 必填（3.0 已把 2.x 的 url 拆成 host + pathname）');
          if (sv['url'] !== undefined) err(label + ' 仍在用 2.x 的 url 字段，3.0 应改为 host');
        } else if (!sv['url']) err(label + '.url 必填');
        var proto = sv['protocol'];
        if (!proto) err(label + '.protocol 必填');
        else {
          var pi = protocolInfo(proto);
          if (!pi) warn(label + ' 使用了不常见的协议 ' + proto + '，工具链可能不认识');
          else ok(label + ' 协议 ' + proto + '：' + pi.note);
        }
        var host = String(sv['host'] || sv['url'] || '');
        if (/^(ws|http):/i.test(host) || String(proto).toLowerCase() === 'ws' || String(proto).toLowerCase() === 'http')
          warn(label + ' 使用明文协议，生产环境应换成加密版本');
      }
    }

    // channels
    var channels = doc['channels'];
    var chanKeys = keys(channels);
    if (!isMap(channels) || !chanKeys.length) err('缺少 channels，AsyncAPI 文档至少要描述一个通道');

    var addrSeen = {}, styles = {};
    for (var c = 0; c < chanKeys.length; c++){
      var name = chanKeys[c], ch = channels[name], lbl = 'channels.' + name;
      if (!isMap(ch)){ err(lbl + ' 必须是映射'); continue; }
      if (v3){
        var addr = ch['address'];
        if (addr === undefined) warn(lbl + ' 未声明 address，3.0 里通道键只是标识符，真实地址要写在 address');
        else {
          if (addrSeen[addr]) err('地址 ' + addr + ' 被 ' + addrSeen[addr] + ' 和 ' + name + ' 重复占用');
          else addrSeen[addr] = name;
          var st = addressStyle(addr);
          styles[st.style] = (styles[st.style] || 0) + 1;
          if (st.wildcard) warn(lbl + ' 的地址含通配符，通配符只应出现在订阅侧而不是文档定义里');
          if (st.hasParam && !isMap(ch['parameters']))
            err(lbl + ' 地址里有 {参数} 占位符，但没有对应的 parameters 定义');
        }
        if (!isMap(ch['messages']) || !keys(ch['messages']).length)
          err(lbl + ' 未声明 messages，通道上跑什么消息是文档的核心信息');
        if (ch['publish'] !== undefined || ch['subscribe'] !== undefined)
          err(lbl + ' 仍在用 2.x 的 publish/subscribe，3.0 要改成顶层 operations 加 action');
      } else {
        if (ch['publish'] === undefined && ch['subscribe'] === undefined)
          warn(lbl + ' 既没有 publish 也没有 subscribe');
      }
    }
    if (keys(styles).length > 1)
      warn('通道地址风格不统一（' + keys(styles).map(function(k){ return k + ' ' + styles[k] + ' 个'; }).join('、') +
           '），同一套系统应固定用点号或斜杠分层');

    // operations（3.0 才有）
    var ops = doc['operations'], opKeys = keys(ops);
    if (v3){
      if (!isMap(ops) || !opKeys.length) err('3.0 文档缺少顶层 operations');
      var sendCount = 0, recvCount = 0;
      for (var o = 0; o < opKeys.length; o++){
        var oid = opKeys[o], op = ops[oid], ol = 'operations.' + oid;
        if (!isMap(op)){ err(ol + ' 必须是映射'); continue; }
        var act = op['action'];
        if (!act) err(ol + '.action 必填，取值为 send 或 receive');
        else if (act !== 'send' && act !== 'receive') err(ol + '.action 只能是 send 或 receive，收到 ' + act);
        else if (act === 'send') sendCount++; else recvCount++;
        var chRef = op['channel'];
        if (!isMap(chRef) || !chRef['$ref']) err(ol + '.channel 必须是指向通道的 $ref');
        else {
          var rr = resolveRef(doc, chRef['$ref']);
          if (rr.error) err(ol + '.channel ' + rr.error);
          else if (chRef['$ref'].indexOf('#/channels/') !== 0)
            warn(ol + '.channel 的引用不指向 #/channels/，工具链可能无法关联');
        }
        if (!op['summary'] && !op['description']) warn(ol + ' 缺少 summary，生成的文档会很难读');
      }
      if (opKeys.length && sendCount === 0)
        warn('所有操作都是 receive，这份文档只描述了消费侧，生产侧契约缺失');
      if (opKeys.length && recvCount === 0)
        warn('所有操作都是 send，没有描述任何消费方');
    }

    // components 与消息载荷
    var comps = doc['components'];
    var msgs = isMap(comps) ? comps['messages'] : null;
    var mk = keys(msgs);
    for (var mi = 0; mi < mk.length; mi++){
      var msg = msgs[mk[mi]], ml = 'components.messages.' + mk[mi];
      if (!isMap(msg)) continue;
      if (msg['payload'] === undefined) err(ml + ' 缺少 payload，消费方无法生成代码');
      if (!msg['name'] && !msg['title']) warn(ml + ' 缺少 name 或 title');
      if (!msg['contentType'] && !doc['defaultContentType'])
        warn(ml + ' 未声明 contentType，且文档也没有 defaultContentType');
      if (isMap(msg['payload']) && msg['payload']['type'] === 'object' && !isMap(msg['payload']['properties']))
        warn(ml + ' 的 payload 声明为 object 却没有 properties，等于没约束');
      if (!isMap(msg['examples']) && !Array.isArray(msg['examples']))
        warn(ml + ' 没有示例消息，联调时全靠口口相传');
    }
    if (!doc['defaultContentType']) warn('建议在顶层声明 defaultContentType，例如 application/json');

    // 安全
    var schemes = isMap(comps) ? comps['securitySchemes'] : null;
    if (!isMap(schemes) || !keys(schemes).length)
      warn('未定义 securitySchemes，事件通道同样需要鉴权说明');

    var errors = 0, warns = 0;
    for (var q = 0; q < iss.length; q++){
      if (iss[q].level === 'error') errors++;
      else if (iss[q].level === 'warn') warns++;
    }
    return {issues:iss, errors:errors, warnings:warns, ok:errors === 0, version:ver.value,
            grade:errors ? '不合规' : (warns ? '可用但有缺口' : '完整')};
  }

  // ---------------- 拓扑与统计 ----------------
  function topology(doc){
    var ver = detectVersion(doc);
    if (ver.error) return {error:ver.error};
    var channels = doc['channels'] || {}, ops = doc['operations'] || {};
    var nodes = [], edges = [];
    var ck = keys(channels);
    for (var i = 0; i < ck.length; i++){
      var ch = channels[ck[i]] || {};
      nodes.push({id:ck[i], address:ch['address'] || ck[i],
                  messages:keys(ch['messages']).length, style:addressStyle(ch['address'] || ck[i]).style});
    }
    var ok2 = keys(ops);
    for (var j = 0; j < ok2.length; j++){
      var op = ops[ok2[j]] || {};
      var ref = isMap(op['channel']) ? String(op['channel']['$ref'] || '') : '';
      var target = ref.indexOf('#/channels/') === 0 ? ref.slice('#/channels/'.length) : null;
      edges.push({operation:ok2[j], action:op['action'] || null, channel:target, dangling:!target || !channels[target]});
    }
    return {value:{nodes:nodes, edges:edges,
                   channelCount:nodes.length, operationCount:edges.length,
                   sends:edges.filter(function(e){ return e.action === 'send'; }).length,
                   receives:edges.filter(function(e){ return e.action === 'receive'; }).length,
                   dangling:edges.filter(function(e){ return e.dangling; }).length}};
  }

